    case t: Tokenizable        => Token(t.toToken, TokenType.STRUCTURED)
    case s: String             => stringTokenizer.tokenize(s)
    case b: Array[Byte]        => stringTokenizer.tokenize(b)
    case n: Int                => numericTokenizer.tokenize(BigDecimal(n))
    case n: Long               => numericTokenizer.tokenize(BigDecimal(n))
    case n: Double             => numericTokenizer.tokenize(n)
    case n: Float              => numericTokenizer.tokenize(n)
    case n: BigDecimal         => numericTokenizer.tokenize(n)
    case dt: LocalDateTime     => temporalTokenizer.tokenize(dt)
    case d: LocalDate          => temporalTokenizer.tokenize(d)
    case other                 => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

/**
 * Registry with complex nested generic types.
 */
class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private val _handlers = ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry += (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case Some(container) =>
        container.getAll.toList.map {
          case item =>
            _handlers.view.flatMap(h => h(item)).headOption
        }
      case None => Nil
    }
  }
}

/**
 * Simulated functor for tokens.
 */
class TokenFunctor[T](private val _value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(_value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(_value)

  def getOrElse[U >: T](default: => U): U = if (_value != null) _value else default

  def get: T = _value
}

/**
 * Extended monad operations.
 */
class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(this.get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

/**
 * Tokenizer for JSON structures using Circe.
 */
class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split('.')
    val found = parts.foldLeft(Option(value)) { (acc, part) =>
      acc.flatMap {
        case current =>
          if (current.isObject) {
            current.asObject.flatMap(_.apply(part))
          } else if (current.isArray && part.forall(_.isDigit)) {
            val idx = part.toInt
            current.asArray.flatMap(arr => if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None)
          } else {
            None
          }
      }
    }
    found.map(tokenize)
  }
}

/**
 * Basic tokenizer that splits text by whitespace.
 */
class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var w = if (stripPunctuation) word.filterNot(punctuation) else word
    if (lowercase) w = w.toLowerCase

    if (w.length < minLength) return None

    maxLength.foreach {
      case max =>
        if (w.length > max) w = w.substring(0, max)
    }

    if (w.isEmpty) None else Some(w)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap {
      case (word, i) =>
        processToken(word).map {
          case processed =>
            Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
        }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    var currentPos = 0
    words.toList.flatMap {
      case word =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length
        currentPos = end

        processToken(word).map { processed => (processed, start, end) }
    }
  }

  def countTokens(text: String): Int = tokenize(text).size
}

/**
 * Fluent builder for creating tokenizers.
 */
class TokenizerBuilder[T] {
  private val _normalizers = ListBuffer.empty[String => String]
  private val _validators = ListBuffer.empty[T => Boolean]
  private var _metadata = Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    _validators += validator
    this
  }

  def withMetadata(metadata: (String, Any)*): TokenizerBuilder[T] = {
    _metadata ++= metadata
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    (value: T) => {
      validators.foreach {
        case validator =>
          if (!validator(value)) {
            throw new IllegalArgumentException(s"Validation failed for $value")
          }
      }

      var strValue = value.toString
      normalizers.foreach {
        case normalizer =>
          strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
